// 1. Получаем данные
const item = $input.first().json;
const prefix = item.prefix_image_url || "https://blog.example.com/wp-content/uploads/";

// 2. Генерация случайных просмотров
// ЗАКОММЕНТИРОВАНО 2026-09-16: отключили фейковый счётчик прочтений в статьях (не удалено, может понадобиться).
// const viewsCount = Math.floor(Math.random() * 10000) + 5000;
// const views = viewsCount.toLocaleString('en-US').replace(/,/g, ' ');

// 3. Форматирование дат
const date = new Date();
const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const dateFormatted = `${date.getDate()} ${months[date.getMonth()]} ${date.getFullYear()}`;
const dateISO = date.toISOString();

// 4. Функция для сборки URL (берет готовую переменную или делает замену в main_image)
const getUrl = (fileName, index) => {
  if (fileName) return prefix + fileName;
  // Если переменная пустая, берем main_image и меняем inline1 на inlineN
  return prefix + item.main_image.replace('inline1', `inline${index}`);
};

// 5. Возвращаем результат
return [{
  json: {
    ...item,
    // views: views, // ЗАКОММЕНТИРОВАНО 2026-09-16 — фейковый счётчик прочтений отключён
    date_formatted: dateFormatted,
    date_iso: dateISO,
    category_name: item.group_content || "Общее",

    // Сборка финальных URL через префикс
    image_url_1: prefix + item.main_image,
    image_url_2: getUrl(item.image_2_name, 2),
    image_url_3: getUrl(item.image_3_name, 3),
    image_url_4: getUrl(item.image_4_name, 4),
    image_url_5: getUrl(item.image_5_name, 5)
  }
}];

// Получаем данные из предыдущей ноды
const input = $input.all()[0].json;
const fileName = input.main_image || ""; // Например: "belchik-1-inline1.png"

// 1. Убираем расширение (всё после последней точки)
// Если точек несколько, берем всё до последней
const imageSlug = fileName.substring(0, fileName.lastIndexOf('.')) || fileName;

// 2. Возвращаем результат
return [{
    json: {
        ...input, // Пробрасываем старые данные
        image_slug: imageSlug // Получаем "belchik-1-inline1"
    }
}];

const item = $input.item.json;
let html = item.content.parts[0].text;

// 1. Убираем markdown и мусор
html = html
    .replace(/```html|```/g, '')      // Сносим бэктики
    .replace(/<p>&nbsp;<\/p>/g, '')   // Убираем пустые строки
    .trim();

item.content.parts[0].text = html;
return { json: item };

// 1. ПОЛУЧАЕМ ТЕКСТ ОТ GEMINI (локальный вход)
const contentItem = $input.item.json;
const cleanedHtml = contentItem.content.parts[0].text;

// 2. ПОЛУЧАЕМ МЕТАДАННЫЕ ИЗ НАЧАЛА
const metadata = $('Code in JavaScript1').item.json;
const prefix = "https://blog.example.com/wp-content/uploads/";

const articleTitle = metadata.article_title || "Внешнеэкономическая деятельность";
const dateFormatted = metadata.date_formatted || "16 марта 2026";
// ЗАКОММЕНТИРОВАНО 2026-09-16: отключили фейковый счётчик прочтений (не удалено, может понадобиться).
// const viewsCount = metadata.views || "5 000";
const category = metadata.group_content || "ВЭД";
const mainImg = metadata.main_image || "exampleblog-1-inline1.png";
const rawLinks = metadata.links || ""; 
const focusLink = metadata.focus_link || "https://example.com"; // Ссылка для кнопки

// 3. ЛОГИКА ИЗОБРАЖЕНИЙ (inline 2-5)
const imageMatch = mainImg.match(/-(\d+)-/);
const imageId = imageMatch ? imageMatch[1] : "1";
const inlineImages = [];
for (let i = 2; i <= 5; i++) {
    inlineImages.push(`${prefix}exampleblog-${imageId}-inline${i}.png`);
}

// 4. ТРАНСЛИТЕРАЦИЯ ДЛЯ ID
const slugify = (text) => {
    const r = {'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'h','ц':'ts','ч':'ch','ш':'sh','щ':'sch','ы':'y','э':'e','ю':'yu','я':'ya'};
    return text.toString().toLowerCase().trim().split('').map(c => r[c] || (/[a-z0-9]/.test(c) ? c : '-')).join('').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
};

// 5. ГЕНЕРАЦИЯ TOC И ВСТАВКА КАРТИНОК
let imgIndex = 0;
let tocItems = [];
const processedHtml = cleanedHtml.replace(/<h2[^>]*>(.*?)<\/h2>/gi, (match, title) => {
    const cleanTitle = title.replace(/<[^>]+>/g, ''); 
    const id = slugify(cleanTitle) || 'section-' + (imgIndex + 1);
    tocItems.push({ id, title: cleanTitle });
    let result = `<h2 id="${id}">${cleanTitle}</h2>`;
    if (imgIndex < inlineImages.length) {
        result = `<img src="${inlineImages[imgIndex]}" alt="Иллюстрация: ${cleanTitle}" class="gp-ckb-img" style="margin: 30px 0; border-radius: 8px;">\n` + result;
        imgIndex++;
    }
    return result;
});

// 6. СБОРКА БЛОКА "ЧИТАТЬ ТАКЖЕ"
let relatedSection = "";
if (rawLinks) {
    try {
        const linksArray = typeof rawLinks === 'string' ? JSON.parse(rawLinks) : rawLinks;
        const cards = linksArray.slice(0, 5).map(link => `
            <div class="gp-ckb-related-card">
                <div class="gp-ckb-related-img" style="background-image:url('${link.image}')"></div>
                <div class="gp-ckb-related-body">
                    <h3><a href="${link.link}" target="_blank">${link.title}</a></h3>
                    <span class="gp-ckb-related-meta">${link.date || ''} • ${link.time || ''}</span>
                </div>
            </div>`).join('');
        relatedSection = `<div class="gp-ckb-related-wrapper"><h2 class="gp-ckb-related-title">Читайте также</h2><div class="gp-ckb-related-grid">${cards}</div></div>`;
    } catch (e) { console.error("Links parse error", e); }
}

const tocHtml = tocItems.map(i => `<li class="toc-h2"><a href="#${i.id}">${i.title}</a></li>`).join('');

// 7. ФИНАЛЬНЫЙ ШАБЛОН
const finalLayout = `
<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": "${articleTitle}",
  "image": "${prefix + mainImg}",
  "author": {"@type": "Person", "name": "Алексей Яценко"},
  "publisher": {"@type": "Organization", "name": "Блог компании https://example.com"},
  "datePublished": "${metadata.date_iso || new Date().toISOString()}",
  "url": "${metadata.url_page || ''}"
}
</script>

<div class="gp-ckb-layout">
    <article class="gp-ckb-article">
        <div class="gp-ckb-breadcrumbs" style="padding: 15px 0;">
            <a href="/" style="color: #0066cc; text-decoration: none;">Главная</a><span style="margin: 0 8px;">|</span>
            <a href="/blog" style="color: #0066cc; text-decoration: none;">Блог</a><span style="margin: 0 8px;">|</span>
            <span style="color: #333;">${articleTitle}</span>
        </div>

        <div class="gp-ckb-hero-v2" style="position: relative;">
            <img src="${prefix + mainImg}" alt="${articleTitle}" style="width: 100%; height: auto; object-fit: cover;">
            <div style="position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.2) 60%, transparent 100%); display: flex; flex-direction: column; justify-content: flex-end; padding: 50px 10% 40px;">
                <div style="background: #3b82f6; color: white; padding: 4px 12px; border-radius: 4px; font-size: 11px; font-weight: 700; width: fit-content; margin-bottom: 20px; text-transform: uppercase;">${category}</div>
                <div style="color: white; font-size: clamp(24px, 5vw, 42px); font-weight: 800; line-height: 1.1; margin-bottom: 20px; text-shadow: 0 2px 10px rgba(0,0,0,0.3);">${articleTitle}</div>
                <div style="display: flex; gap: 20px; color: rgba(255,255,255,0.8); font-size: 13px;">
                    <span>📅 ${dateFormatted}</span>
                    <!-- ЗАКОММЕНТИРОВАНО 2026-09-16 — фейковый счётчик прочтений отключён (не удалено, может понадобиться):
                    <span>👁 \${viewsCount} прочтений</span>
                    -->
                </div>
            </div>
        </div>

        <div class="gp-ckb-text-container">
            ${processedHtml}
            <div style="text-align: center; margin: 50px 0;">
                <a href="${focusLink}" target="_blank" class="gp-ckb-btn" style="display: inline-flex; align-items: center; justify-content: center; border: none; outline: none; text-decoration: none;">
                    <span class="gp-ckb-btn-inner" style="color: white; font-weight: 700; padding: 0 40px;">ПОЛУЧИТЬ КОНСУЛЬТАЦИЮ</span>
                </a>
            </div>
        </div>
    </article>
    <aside class="gp-ckb-toc"><div class="gp-ckb-toc-inner"><ul>${tocHtml}</ul></div></aside>
</div>

${relatedSection}

<script>
document.addEventListener('DOMContentLoaded', function() {
    var headings = document.querySelectorAll('.gp-ckb-article h2[id]');
    var tocLinks = document.querySelectorAll('.gp-ckb-toc a');
    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                tocLinks.forEach(function(link) {
                    link.parentElement.classList.remove('toc-active');
                    if (link.getAttribute('href') === '#' + entry.target.id) { link.parentElement.classList.add('toc-active'); }
                });
            }
        });
    }, { rootMargin: '0px 0px -60% 0px' });
    headings.forEach(function(h) { observer.observe(h); });
});
</script>
`;

contentItem.content.parts[0].text = finalLayout;
return { json: contentItem };
